def kth_element(arr, k):
    # Ensure k is within the valid range
    k -= 1  # Convert to 0-based indexing

    # Helper function to ensure we work with positive k
    def get_kth_element(arr, k):
        n = len(arr)
        if n == 0 or k < 0 or k >= n:
            return None

        if k == 0:
            return arr[0]

        left, right = 0, n - 1

        while left <= right:
            mid = (left + right) // 2

            if mid > k:
                right = mid - 1
            elif mid < k:
                left = mid + 1
            else:
                # mid is exactly k-th element
                return arr[mid]

        return None

    result = get_kth_element(arr, k)
    return result

