def amicable_numbers_sum(limit):
    def sum_proper_divisors(n):
        """Return the sum of proper divisors of n."""
        total = 1  # Start with 1 since it's a divisor for all n > 1
        sqrt_n = int(n**0.5)
        for i in range(2, sqrt_n + 1):
            if n % i == 0:
                total += i
                if i != n // i:  # Add the quotient only if it's not the square root
                    total += n // i
        return total

    amicable_pairs = set()
    for num in range(2, limit + 1):
        if num in amicable_pairs:
            continue
        pair_sum = sum_proper_divisors(num)
        if pair_sum > num and sum_proper_divisors(pair_sum) == num:
            amicable_pairs.add(num)
            amicable_pairs.add(pair_sum)

    return sum(amicable_pairs)

