def reverse_vowels(s):
    def swap_vowels(s, start, end):
        vowels = 'aeiouAEIOU'
        while start < end:
            if s[start] not in vowels:
                start += 1
            if s[end] not in vowels:
                end -= 1
            if s[start] in vowels and s[end] in vowels:
                s = list(s)
                s[start], s[end] = s[end], s[start]
                s = ''.join(s)
                start += 1
                end -= 1
        return s

    vowels_indices = [i for i, char in enumerate(s) if char in 'aeiouAEIOU']
    length = len(vowels_indices)

    result = list(s)
    for i, index in enumerate(vowels_indices):
        result[index] = s[vowels_indices[(length - 1 - i) % length]]

    return ''.join(result)

