def max_sum(arr):
    n = len(arr)

    # dp[i] stores the maximum sum of increasing subsequence ending at i
    dp_increasing = arr.copy()
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                dp_increasing[i] = max(dp_increasing[i], dp_increasing[j] + arr[i])

    # dp_decreasing[i] stores the maximum sum of decreasing subsequence starting at i
    dp_decreasing = arr.copy()
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[i] > arr[j]:
                dp_decreasing[i] = max(dp_decreasing[i], dp_decreasing[j] + arr[i])

    # The maximum bitonic subsequence sum is the maximum value of dp_increasing[i] + dp_decreasing[i] - arr[i] for all i
    max_bitonic_sum = float('-inf')
    for i in range(n):
        max_bitonic_sum = max(max_bitonic_sum, dp_increasing[i] + dp_decreasing[i] - arr[i])

    return max_bitonic_sum

