def check_min_heap(arr):
    def is_valid(index):
        # Check if all left and right children of arr[index] exist and satisfy the heap property
        left_child = 2 * index + 1
        right_child = 2 * index + 2
        if left_child < len(arr) and arr[index] > arr[left_child]:
            return False
        if right_child < len(arr) and arr[index] > arr[right_child]:
            return False
        return True

    # Start the validation from the first non-leaf node, which is at index (n // 2 - 1)
    n = len(arr)
    for i in range(n // 2 - 1, -1, -1):
        if not is_valid(i):
            return False
    return True

